        node = node.node_link
    node.node_link = target_node

def update_tree(items, node, header_table, count):
    first_item = items[0]
    if first_item in node.children:
        node.children[first_item].increment(count)
    else:
        node.children[first_item] = TreeNode(first_item, count, node)
        if header_table[first_item][1] is None:
