    if len(items) > 1:
        update_tree(items[1:], node.children[first_item], header_table, count)

def create_tree(transactions, min_support):
    header_table = {}
    for transaction in transactions:
        for item in transaction:
            header_table[item] = header_table.get(item, 0) + transactions[transaction]

    header_table = {k: v for k, v in header_table.items() if v >= min_support}
    freq_item_set = set(header_table.keys())
    if len(freq_item_set) == 0:
        return None, None

    for k in header_table:
        header_table[k] = [header_table[k], None]

    root = TreeNode('Null', 1, None)
    for transaction, count in transactions.items():
        local_items = {}
